import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"板","description":"","frontmatter":{"title":"板","date":"2026-11-09T00:00:00.000Z","seq":20,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/板.md","filePath":"blogs/诗经·大雅/板.md"}'),o={name:"blogs/诗经·大雅/板.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="板" tabindex="-1">板 <a class="header-anchor" href="#板" aria-label="Permalink to &quot;板&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　生民之什</p><div class="poem"><p class="poem-stanza">上帝板板，下民卒瘅。出话不然，为犹不远。</p><p class="poem-stanza">靡圣管管。不实于亶。犹之未远，是用大谏。</p><p class="poem-stanza">天之方难，无然宪宪。天之方蹶，无然泄泄。</p><p class="poem-stanza">辞之辑矣，民之洽矣。辞之怿矣，民之莫矣。</p><p class="poem-stanza">我虽异事，及尔同僚。我即尔谋，听我嚣嚣。</p><p class="poem-stanza">我言维服，勿以为笑。先民有言，询于刍荛。</p><p class="poem-stanza">天之方虐，无然谑谑。老夫灌灌，小子蹻蹻。</p><p class="poem-stanza">匪我言耄，尔用忧谑。多将熇熇，不可救药。</p><p class="poem-stanza">天之方懠。无为夸毗。威仪卒迷，善人载尸。</p><p class="poem-stanza">民之方殿屎，则莫我敢葵？丧乱蔑资，曾莫惠我师？</p><p class="poem-stanza">天之牖民，如埙如篪，如璋如圭，如取如携。</p><p class="poem-stanza">携无曰益，牖民孔易。民之多辟，无自立辟。</p><p class="poem-stanza">价人维藩，大师维垣，大邦维屏，大宗维翰，</p><p class="poem-stanza">怀德维宁，宗子维城。无俾城坏，无独斯畏。</p><p class="poem-stanza">敬天之怒，无敢戏豫。敬天之渝，无敢驰驱。</p><p class="poem-stanza">昊天曰明，及尔出王。昊天曰旦，及尔游衍。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
